describe("deepMerge", () => {
  it("merges simple properties", () => {
    const base = { a: 1, b: 2 };
    const patch = { b: 3, c: 4 };
    const result = deepMerge(base, patch);
    assert.deepEqual(result, { a: 1, b: 3, c: 4 });
  });

  it("replaces arrays instead of merging", () => {
    const base = { arr: [1, 2, 3] };
    const patch = { arr: [4, 5] };
    const result = deepMerge(base, patch);
    assert.deepEqual(result, { arr: [4, 5] });
  });

  it("replaces scalars", () => {
    const base = { val: "original" };
    const patch = { val: "new" };
    const result = deepMerge(base, patch);
    assert.equal(result.val, "new");
  });

  it("recursively merges nested objects", () => {
    const base = { a: { x: 1, y: 2 }, z: 3 };
    const patch = { a: { y: 20, z: 21 } };
    const result = deepMerge(base, patch);
    assert.deepEqual(result, { a: { x: 1, y: 20, z: 21 }, z: 3 });
  });

  it("handles deep nesting", () => {
    const base = { a: { b: { c: 1 } } };
    const patch = { a: { b: { d: 2 } } };
    const result = deepMerge(base, patch);
    assert.deepEqual(result, { a: { b: { c: 1, d: 2 } } });
  });

  it("does not mutate the original base", () => {
    const base = { a: { x: 1 } };
    const patch = { a: { y: 2 } };
    const baseCopy = JSON.parse(JSON.stringify(base));
    deepMerge(base, patch);
    assert.deepEqual(base, baseCopy);
  });

  it("handles empty objects", () => {
    assert.deepEqual(deepMerge({}, { a: 1 }), { a: 1 });
    assert.deepEqual(deepMerge({ a: 1 }, {}), { a: 1 });
  });

  it("overwrites nested objects with scalars", () => {
    const base = { a: { x: 1 } };
    const patch = { a: "scalar" };
    const result = deepMerge(base, patch);
    assert.equal(result.a, "scalar");
  });
