export const DASHBOARD_URL = "https://duelagents.com/dashboard/settings";
export const KEY_DOCS_URL = "https://duelagents.com/dashboard/settings";

const API_KEY_PATTERN = /^duel_[0-9a-zA-Z]{8}_[0-9a-zA-Z]{32}$/;

export type InstallTarget =
  | "claude-code"
  | "cursor"
  | "codex"
  | "openclaw"
  | "openai-compat";

export interface ConnectivityResult {
  ok: boolean;
  status: "ok" | "unauthorized" | "unreachable" | "invalid_key";
  message: string;
  httpStatus?: number;
}

export function validateApiKey(plaintext: string | undefined | null): boolean {
  if (!plaintext) return false;
  return API_KEY_PATTERN.test(plaintext);
}

export function requireApiKey(input: string | undefined | null, label = "DUEL_API_KEY"): string {
  if (!validateApiKey(input)) throw new Error(`Invalid or missing ${label}`);
  return input as string;
}

export function getProxyUrl(): string {
  const url = process.env.DUEL_PROXY_URL || DEFAULT_PROXY_URL;
  return url.replace(/\/+$/, "");
}

export function getEnvForTarget(target: InstallTarget, apiKey: string, proxyUrl = getProxyUrl()): Record<string, string> {
  requireApiKey(apiKey);
  if (target === "openai-compat") {
    return { OPENAI_API_KEY: apiKey, OPENAI_BASE_URL: proxyUrl };
  }
  return { DUEL_API_KEY: apiKey, DUEL_PROXY_URL: proxyUrl };
}

export function buildOpenClawPatch(apiKey: string, proxyUrl = getProxyUrl()): Record<string, unknown> {
  requireApiKey(apiKey);
  return {
    agents: {
      providers: {
        duel: {
          base_url: proxyUrl,
          api_key_env: "DUEL_API_KEY",
          api_key_value: "${DUEL_API_KEY}",
        },
      },
      defaults: { provider: "duel" },
    },
    env: { DUEL_PROXY_URL: proxyUrl },
  };
}

export function deepMerge(base: Record<string, unknown>, patch: Record<string, unknown>): Record<string, unknown> {
  const result = { ...base };
  for (const key in patch) {
    const patchValue = patch[key];
    const baseValue = result[key];
    if (Array.isArray(patchValue)) {
      result[key] = patchValue;
    } else if (patchValue !== null && typeof patchValue === "object" && !Array.isArray(patchValue) && baseValue !== null && typeof baseValue === "object" && !Array.isArray(baseValue)) {
      result[key] = deepMerge(baseValue as Record<string, unknown>, patchValue as Record<string, unknown>);
    } else {
      result[key] = patchValue;
    }
  }
  return result;
}

export async function checkConnectivity(apiKey: string, proxyUrl = getProxyUrl()): Promise<ConnectivityResult> {
  requireApiKey(apiKey);
  try {
    const response = await fetch(`${proxyUrl}/models`, { headers: { Authorization: `Bearer ${apiKey}` } });
    if (response.ok) {
      return { ok: true, status: "ok", message: "Connected successfully" };
    } else if (response.status === 401) {
      return { ok: false, status: "unauthorized", message: "Invalid API key", httpStatus: 401 };
    } else {
      return { ok: false, status: "unreachable", message: `HTTP ${response.status}`, httpStatus: response.status };
    }
  } catch (error) {
    return { ok: false, status: "unreachable", message: `Network error: ${error instanceof Error ? error.message : String(error)}` };
  }
}
